"Тема кратко говорит, о чём письмо.": "Тақырып хаттың не туралы екенін қысқаша айтады.",
"Вложение — файл, прикреплённый к письму.": "Тіркеме — хатқа тіркелген файл.",
"папки": "қалталар",
"Входящие — полученные, Отправленные — твои письма, Спам — подозрительные.": "Кіріс — алынған хаттар, Жіберілген — өзіңнің хаттарың, Спам — күмәнділер.",
"В письме поздоровайся и поблагодари.": "Хатта амандас және алғыс айт.",
"Использовать вложенные циклы, логику и сравнение": "Кірістірілген циклдерді, логика мен салыстыруды қолдану",
"Теперь программы станут умнее. Нажимай на карточки.": "Енді бағдарламалар ақылдырақ болады. Карточкаларды бас.",
"Вложенный цикл — цикл внутри цикла. Так рисуют узоры и сетки.": "Кірістірілген цикл — цикл ішіндегі цикл. Осылай өрнектер мен торлар салады.",
