"Урок 21. Информация для презентации. Создание проекта": "21-сабақ. Презентацияға арналған ақпарат. Жоба жасау",
"Урок 21. Информация для презентации. Создание проекта — Білім Аралы": "21-сабақ. Презентацияға арналған ақпарат. Жоба жасау — Білім Аралы",
