"Что нужно сделать, чтобы сохранить проект?": "Жобаны сақтау үшін не істеу керек?",
"Что обычно делают сразу после сбора материалов в папку?": "Материалдарды бумаға жинағаннан кейін әдетте не істейді?",
"Что означает настройка «Задержка»?": "«Кідіріс» параметрі нені білдіреді?",
"Что полезно сделать, когда презентация оформлена и сохранена?": "Презентация ресімделіп, сақталғаннан кейін не істеген пайдалы?",
"Что получится, если применить к надписи текстовый эффект?": "Жазуға мәтіндік әсерді қолданса, не болады?",
"Что поможет найти в эссе слова, которые повторяются?": "Эсседе қайталанатын сөздерді табуға не көмектеседі?",
"Что поможет, если тебе удобнее говорить, чем писать запрос?": "Сұрауды жазғаннан гөрі сөйлеген ыңғайлы болса, не көмектеседі?",
"Что произойдёт с файлом проекта на другом компьютере?": "Жоба файлымен басқа компьютерде не болады?",
"Что происходит с текстом при эффекте «печатная машинка»?": "«Жазу машинкасы» әсерінде мәтінмен не болады?",
"Что стоит сделать с готовой презентацией, чтобы не потерять работу?": "Жұмысты жоғалтпау үшін дайын презентациямен не істеген жөн?",
