"Неверно. Одной длины мало: пароль не должен быть из самых частых": "Дұрыс емес. Бір ұзындық аз: құпия сөз ең жиілерінің қатарынан болмауы керек",
"Неверно. Пароль знает только владелец": "Дұрыс емес. Құпия сөзді тек иесі біледі",
"Неверно. Пароль никому не сообщают": "Дұрыс емес. Құпия сөзді ешкімге айтпайды",
