"Неверно. Пароль нужно хранить в секрете": "Дұрыс емес. Құпия сөзді құпия сақтау керек",
"Неверно. Пароль ставят и на компьютер, телефон, страницы в соцсетях": "Дұрыс емес. Құпия сөзді компьютерге, телефонға, әлеуметтік желідегі беттерге де қояды",
