"Неверно. Получение файлов — тоже этап проекта": "Дұрыс емес. Файлдарды алу да жобаның кезеңі",
"Неверно. Принтер печатает готовый документ, а вводят текст клавиатурой": "Дұрыс емес. Принтер дайын құжатты басып шығарады, ал мәтінді пернетақтамен енгізеді",
"Неверно. Сначала запускают браузер и открывают сайт почты": "Дұрыс емес. Алдымен браузерді іске қосып, пошта сайтын ашады",
"Неверно. Сначала нужно создать и сохранить файл": "Дұрыс емес. Алдымен файлды жасап, сақтау керек",
"Неверно. Сначала нужно спросить взрослого": "Дұрыс емес. Алдымен ересек адамнан сұрау керек",
