"Никому не сообщай": "Ешкімге айтпа",
"Новые письма приходят в папку «Входящие». Открой письмо, загрузи вложенный файл и отправь другу сообщение, что всё получил.": "Жаңа хаттар «Кіріс» қалтасына келеді. Хатты ашып, тіркелген файлды жүктеп ал да, досыңа бәрін алғаныңды хабарла.",
"Новые письма приходят во Входящие": "Жаңа хаттар Кіріске келеді",
"Нужна программа для работы с Интернетом": "Интернетпен жұмыс істеуге арналған бағдарлама қажет",
