"Описывать влияние научно-технического прогресса на изменение компьютеров и мобильных устройств и приводить примеры роботов и областей их применения": "Ғылыми-техникалық прогрестің компьютерлер мен мобильді құрылғылардың өзгеруіне әсерін сипаттау және роботтар мен оларды қолдану салаларының мысалдарын келтіру",
"Описывать порядок отправки письма с файлом и работу с папками электронной почты": "Хатты файлмен жіберу тәртібін және электрондық пошта қалталарымен жұмысты сипаттау",
"Определять критерии надёжного пароля и менять слабый пароль на более надёжный": "Сенімді құпия сөздің өлшемдерін анықтау және әлсіз құпия сөзді неғұрлым сенімдісіне ауыстыру",
"Открыть бесплатную учётную запись может любой пользователь. Нужно запустить браузер, набрать адрес сайта в адресной строке, нажать «Завести новую почту» и заполнить все строки окна.": "Тегін есептік жазбаны кез келген пайдаланушы аша алады. Браузерді іске қосып, сайт мекенжайын мекенжай жолына теріп, «Жаңа пошта ашу» батырмасын басу және терезенің барлық жолдарын толтыру керек.",
"Отправить": "Жіберу",
"Отправляем": "Жіберіп жатырмыз",
"Отправлять пока нечего": "Әзірге жіберетін ештеңе жоқ",
"Ошибка в адресе — письмо уйдёт не туда": "Мекенжайдағы қате — хат басқа жаққа кетеді",
"Папка Корзина нужна для хранения новых писем от друзей.": "Себет қалтасы достардан келген жаңа хаттарды сақтауға қажет.",
