"Пароль от почты можно сообщить любому, кто попросит.": "Поштаның құпия сөзін сұраған кез келген адамға айтуға болады.",
"Пароль от почты никому не сообщай. Письма от незнакомых и вложения без взрослого не открывай, по подозрительным ссылкам не переходи.": "Поштаның құпия сөзін ешкімге айтпа. Бейтаныс адамдардың хаттары мен тіркемелерін ересек адамсыз ашпа, күдікті сілтемелерге өтпе.",
"Пароль ставят и на компьютер, телефон, страницы в соцсетях": "Құпия сөзді компьютерге, телефонға, әлеуметтік желідегі беттерге де қояды",
"Пароль — секретный набор символов, который защищает информацию от чужого доступа. Он нужен для компьютера, телефона, почты и страниц в соцсетях.": "Құпия сөз — ақпаратты бөтен адамның кіруінен қорғайтын құпия таңбалар жиынтығы. Ол компьютерге, телефонға, поштаға және әлеуметтік желідегі беттерге қажет.",
"Пароль — секретный набор символов, который защищает твои данные. Его знаешь только ты.": "Құпия сөз — деректеріңді қорғайтын құпия таңбалар жиынтығы. Оны тек сен білесің.",
"Пароль — тайна": "Құпия сөз — құпия",
"Пароль — только для владельца ящика": "Құпия сөз — тек жәшік иесіне арналған",
"Перед отправкой полезно проверить, верно ли написан адрес получателя.": "Алушының мекенжайы дұрыс жазылғанын жіберер алдында тексеру пайдалы.",
