"Письма и вложения от незнакомых людей не открывай без взрослого и не переходи по подозрительным ссылкам. Пароль от почты никому не сообщай.": "Бейтаныс адамдардан келген хаттар мен тіркемелерді ересек адамсыз ашпа және күдікті сілтемелерге өтпе. Пошта құпия сөзін ешкімге айтпа.",
