"Почему большое видео загружается дольше, чем короткое эссе?": "Неліктен үлкен бейне қысқа эссеге қарағанда ұзағырақ жүктеледі?",
"Почему видео отправляется дольше, чем небольшое эссе?": "Неліктен бейне шағын эссеге қарағанда ұзағырақ жіберіледі?",
"Почему короткий пароль плох?": "Неліктен қысқа құпия сөз жақсы емес?",
"Почему нельзя делать пароль только из имени и даты рождения?": "Неліктен құпия сөзді тек аты мен туған күнінен жасауға болмайды?",
"Почему слишком короткий пароль плох?": "Неліктен тым қысқа құпия сөз жақсы емес?",
"Почта передаёт не только слова": "Пошта тек сөздерді ғана жеткізбейді",
