"Применять команды загрузки и передачи файлов по электронной почте и выполнять проект по этапам": "Файлдарды электрондық пошта арқылы жүктеу және жіберу пәрмендерін қолдану және жобаны кезеңдер бойынша орындау",
"Принтер нужен, чтобы вводить текст в компьютер.": "Принтер компьютерге мәтін енгізу үшін қажет.",
"Принтер печатает готовый документ, а вводят текст клавиатурой": "Принтер дайын құжатты басып шығарады, ал мәтінді пернетақтамен енгізеді",
"Пришло письмо с вложением от незнакомого человека. Как поступить?": "Белгісіз адамнан тіркемесі бар хат келді. Қалай әрекет ету керек?",
