"Работает на карманном устройстве": "Қалта құрылғыда жұмыс істейді",
"Раньше и сейчас": "Бұрын және қазір",
"Раньше роботы выполняли только определённую работу, а сегодня могут, например, обучать.": "Бұрын роботтар тек белгілі бір жұмысты орындайтын, ал бүгін, мысалы, оқыта да алады.",
"Раньше текст печатали на печатных машинках: ошибку трудно исправить. Благодаря научно-техническому прогрессу появились компьютеры и принтеры: текст можно набрать, поправить и только потом распечатать.": "Бұрын мәтінді жазу машинкаларында басатын: қатені түзету қиын болатын. Ғылыми-техникалық прогресс арқасында компьютерлер мен принтерлер пайда болды: мәтінді теріп, түзетіп, тек содан кейін ғана басып шығаруға болады.",
"Реальные пароли можно писать в примерах для друзей.": "Достарға арналған мысалдарға нақты құпия сөздерді жазуға болады.",
"Регистрация в почте начинается с отправки письма другу.": "Поштада тіркелу досына хат жіберуден басталады.",
"Регистрация доступна всем": "Тіркелу барлығына қолжетімді",
