"Робот — автоматизированное устройство, которым управляет человек. Бывают бытовые роботы, помощники людям, роботы-игрушки и интеллектуальные роботы.": "Робот — адам басқаратын автоматтандырылған құрылғы. Тұрмыстық роботтар, адамдарға көмекшілер, ойыншық роботтар және зияткерлік роботтар болады.",
"Роботы-игрушки": "Ойыншық роботтар",
"Сейчас они умеют гораздо больше": "Қазір олар әлдеқайда көп нәрсе істей алады",
