"Скачивать полученные по почте файлы в проекте не нужно.": "Жобада пошта арқылы алынған файлдарды жүктеп алудың қажеті жоқ.",
"Скачивать программы из Интернета нужно вместе со взрослым.": "Интернеттен бағдарламаларды ересек адаммен бірге жүктеу керек.",
