"Современные компьютеры уже умеют распознавать информацию по звуку и имеют сенсорный экран. Учёные работают над молекулярными, био-, оптическими и квантовыми компьютерами.": "Қазіргі компьютерлер дыбыс арқылы ақпаратты тануды әлі де біледі және сенсорлы экраны бар. Ғалымдар молекулалық, био-, оптикалық және кванттық компьютерлер жасау бойынша жұмыс істеп жатыр.",
"Современные роботы умеют, например, готовить еду.": "Қазіргі роботтар, мысалы, тамақ дайындай алады.",
