"У работ есть авторы, и их права защищены законом": "Жұмыстардың авторлары бар, және олардың құқықтары заңмен қорғалған",
"У современных компьютеров бывает сенсорный экран.": "Қазіргі компьютерлерде сенсорлы экран болады.",
"У этого значка много забавных названий": "Бұл белгінің көңілді атаулары көп",
