"Урок 27. Передача данных через Интернет — Білім Аралы": "27-сабақ. Интернет арқылы деректерді жіберу — Білім Аралы",
"Урок 28. Использование электронной почты для приема и передачи данных": "28-сабақ. Деректерді қабылдау және жіберу үшін электрондық поштаны пайдалану",
"Урок 28. Использование электронной почты для приема и передачи данных — Білім Аралы": "28-сабақ. Деректерді қабылдау және жіберу үшін электрондық поштаны пайдалану — Білім Аралы",
"Урок 29. Надежность пароля": "29-сабақ. Құпия сөздің сенімділігі",
"Урок 29. Надежность пароля — Білім Аралы": "29-сабақ. Құпия сөздің сенімділігі — Білім Аралы",
"Урок 30. Передача данных через Интернет. Создание проекта": "30-сабақ. Интернет арқылы деректерді жіберу. Жоба жасау",
"Урок 30. Передача данных через Интернет. Создание проекта — Білім Аралы": "30-сабақ. Интернет арқылы деректерді жіберу. Жоба жасау — Білім Аралы",
"Урок 31. Надёжность пароля. Создание проекта": "31-сабақ. Құпия сөздің сенімділігі. Жоба жасау",
"Урок 31. Надёжность пароля. Создание проекта — Білім Аралы": "31-сабақ. Құпия сөздің сенімділігі. Жоба жасау — Білім Аралы",
"Урок 32. Компьютеры будущего": "32-сабақ. Болашақ компьютерлері",
