"Файл нужно присоединить к письму": "Файлды хатқа қосу керек",
"Файл прикреплять необязательно": "Файлды тіркеу міндетті емес",
"Файл удобно сначала сохранить в папке, а потом прикрепить к письму.": "Файлды алдымен қалтаға сақтап, содан кейін хатқа тіркеу ыңғайлы.",
"Файл уже готов": "Файл әлдеқашан дайын",
"Файлы бывают разные": "Файлдар әртүрлі болады",
"Цель проекта — передавать файлы по электронной почте. Ход работы: создать файлы в программах, сохранить их в папке, отправить нескольким контактам и скачать то, что пришло.": "Жобаның мақсаты — файлдарды электрондық пошта арқылы жіберу. Жұмыс барысы: бағдарламаларда файлдар жасау, оларды қалтаға сақтау, бірнеше байланысқа жіберу және келгенін жүктеп алу.",
"Части адреса": "Мекенжай бөліктері",
"Части адреса электронной почты пишут через пробелы.": "Электрондық пошта мекенжайының бөліктерін бос орындар арқылы жазады.",
"Части письма": "Хат бөліктері",
"Человек задаёт ему задачу": "Оған тапсырманы адам береді",
"Чем длиннее, тем труднее подобрать": "Ұзын болған сайын таңдап табу қиын",
"Чем интеллектуальный робот отличается от простого заводного?": "Зияткерлік робот қарапайым механикалық роботтан немен ерекшеленеді?",
"Чем набор текста на компьютере удобнее, чем на печатной машинке?": "Компьютерде мәтін теру жазу машинкасына қарағанда немен ыңғайлы?",
"Чем удобны современные ноутбуки в поездках?": "Қазіргі ноутбуктер сапарда немен ыңғайлы?",
"Через него ходят по страницам Интернета": "Ол арқылы Интернет беттерімен жүреді",
"Через электронную почту можно отправить файл, например фотографию.": "Электрондық пошта арқылы файлды, мысалы, фотосуретті жіберуге болады.",
"Черновики": "Қараламалар",
"Что где делаем?": "Қайда не істейміз?",
