"Что делать, если кто-то вошёл в твою электронную почту?": "Біреу сенің электрондық поштаңа кірсе, не істеу керек?",
"Что делать, если пришло письмо с вложением от незнакомого человека?": "Бейтаныс адамнан тіркемесі бар хат келсе, не істеу керек?",
"Что делают первым при регистрации в почте?": "Поштада тіркелгенде алдымен не істейді?",
"Что делают с презентацией, чтобы оформить её?": "Презентацияны безендіру үшін онымен не істейді?",
