"Что можно сделать с папкой через контекстное меню?": "Мәзірдің көмегімен қалтамен не істеуге болады?",
"Что нельзя делать при выборе пароля?": "Құпия сөзді таңдағанда не істеуге болмайды?",
"Что нужно делать, если берёшь чужой текст или картинку из Интернета?": "Интернеттен біреудің мәтінін немесе суретін алсаң, не істеу керек?",
"Что нужно записать в блокнот после регистрации на сайте?": "Сайтта тіркелгеннен кейін блокнотқа не жазу керек?",
