"Эссе о первом космонавте Казахстане Токтаре Аубакирове набирают в текстовом редакторе Word, добавляют фотографии из Интернета и дают название. Презентацию из 3–4 слайдов о Талгате Мусабаеве делают в PowerPoint и оформляют фоном и анимацией. Видеофильм об Айдыне Айымбетове загружают из Интернета.": "Қазақстанның тұңғыш ғарышкері Тоқтар Әубәкіров туралы эссені Word мәтіндік редакторында теріп, Интернеттен фотосуреттер қосып, атау береді. Талғат Мұсабаев туралы 3–4 слайдтан тұратын презентацияны PowerPoint-та жасап, фонмен және анимациямен безендіреді. Айдын Айымбетов туралы бейнефильмді Интернеттен жүктейді.",
